  notices: readonly NobleBodyNightNotice[],
): void {
  for (const n of notices)
    events.push(
      n.kind === "night_noble"
        ? {
            timestamp: Date.now(),
            type: "noble_night_notified",
            payload: {
              policy: NOBLE_SECRET_BODY_POLICY,
              actorId: n.actorId,
              day: n.day,
              ...n.known,
            },
            audience: Object.freeze([n.actorId]),
          }
        : {
            timestamp: Date.now(),
            type: "secret_body_night_notified",
            payload: {
              policy: NOBLE_SECRET_BODY_POLICY,
              actorId: n.actorId,
              day: n.day,
              ...n.known,
            },
            audience: Object.freeze([n.actorId]),
          },
    );
}
export function recordNobleContractClosure(
  world: World,
  day: number,
  receipt: { contractId: string; targetId: number },
  phase: Phase,
) {
  const owned = checkpointNobleBodyAuthority(world, true),
    contract = owned.noble.contracts.find((c) => c.id === receipt.contractId);
  if (
    !contract ||
    contract.status.kind === "pending" ||
    contract.status.day !== day ||
    contract.targetId !== receipt.targetId
  )
    throw Error("noble_contract_fact_invalid");
  const payload = {
    policy: NOBLE_SECRET_BODY_POLICY,
    actorId: owned.nobleId,
    day,
    contractId: contract.id,
    targetId: contract.targetId,
    createdNight: contract.createdNight,
    expiresNight: contract.expiresNight,
    ...(contract.status.kind === "expired"
      ? { status: "expired" as const, proposedCause: "servant_expiry" as const }
      : { status: contract.status.kind }),
  };
  getSessionRecorder()?.recordRequiredLogicOp({
    scope: "resolution",
    op: "noble_contract_closed",
    actorId: owned.nobleId,
    phase,
    status: "ok",
    output: payload,
  });
  return Object.freeze(payload);
}

export function appendNobleContractClosure(
  world: World,
  day: number,
  receipt: { contractId: string; targetId: number },
  events: GameEvent[],
  phase: Phase,
): void {
  const payload = recordNobleContractClosure(world, day, receipt, phase);
  events.push({
    timestamp: Date.now(),
    type: "noble_contract_closed",
    payload,
    audience: Object.freeze([]),
  });
}

/**
 * 负责秘密之身最终来源折叠、原名单更新以及上帝事实与录制操作的顺序发布。
 * 输入为经过既有夜间来源检查的同一 sources／deaths 和晚读取的 World／事件；输出原地更新名单与事实。
 * 实际保护付款和唯一原体仍由 authority 拥有，本模块不标死、推进阶段或选择判胜检查点。
 * 先更新来源和名单，再发布事实及必需操作；必需录制失败原样传播，已经付款／写入的前缀不回滚。
 */
import { DeathCause, Phase, type DeathSources, type EntityId, type GameEvent } from "@ai-werewolf-arena/game-contract";
import type { World } from "../../../../core/domain/world";
import { getSessionRecorder } from "../../../../recording/recording_context";
import { safeRecordLogicOp } from "../../../../recording/session_recorder";
import { resolveSecretBodyDamage, checkpointNobleBodyAuthority } from "./authority";
import type { SecretBodySources } from "./damage";

/** 保留原运行引用与晚 getter；字段只读不冻结事件数组，也不创建新的保护或死亡许可。 */
export interface NobleNightDamagePublicationRuntime {
  readonly world: World;
  readonly events: GameEvent[];
}

/** 只在原最终来源检查点同步执行；名单、来源字典和 fact 字段顺序保持原引用与顺序。 */
export function publishNobleNightDamage(
  runtime: NobleNightDamagePublicationRuntime,
  nightDay: number,
  sources: DeathSources,
  deaths: EntityId[],
): void {
  const final = resolveSecretBodyDamage(runtime.world, nightDay, sources as SecretBodySources);
  // 先原地替换来源再重建名单，保留调用方字典和数组身份；后续发布失败不恢复已付保护。
  for (const id of Object.keys(sources)) delete sources[Number(id)];
  for (const [id, causes] of Object.entries(final.sources))
    sources[Number(id)] = causes.map((c) => c as DeathCause);
  deaths.splice(0, deaths.length, ...Object.keys(sources).map(Number));
  if (final.blocked) {
    const actorId = checkpointNobleBodyAuthority(runtime.world, true).bodyId,
      payload = {
        policy: "awa_noble_secret_body_v1" as const,
        actorId,
        day: nightDay,
        ...final.blocked,
      };
    runtime.events.push({
      timestamp: Date.now(),
      type: "secret_body_blocked",
      payload,
      audience: Object.freeze([]),
    });
    getSessionRecorder()?.recordRequiredLogicOp({
      scope: "resolution",
      op: "secret_body_blocked",
      actorId,
      phase: Phase.Night,
      status: "ok",
      output: payload,
    });
  }
  // 上帝来源事实保留同一死因字典，死亡名单另取当时副本；玩家投影不能从空受众读取这份事实。
  const committed = {
    policy: "awa_noble_secret_body_v1" as const,
    actorId: checkpointNobleBodyAuthority(runtime.world, true).bodyId,
    day: nightDay,
    blocked: final.blocked,
    deaths: [...deaths],
    deathSources: sources,
  };
  runtime.events.push({
    timestamp: Date.now(),
    type: "noble_body_sources_committed",
    payload: committed,
    audience: Object.freeze([]),
  });
  getSessionRecorder()?.recordRequiredLogicOp({
    scope: "resolution",
    op: "noble_body_sources_committed",
    phase: Phase.Night,
    status: "ok",
    output: committed,
  });
  // 已发生的必需录制完成之后才写可选诊断；不能把必需录制错误降为可选失败。
  safeRecordLogicOp({
    scope: "resolution",
    op: "night_damage_resolved",
    phase: Phase.Night,
    status: "ok",
    output: { deaths: [...deaths], death_sources: sources },
  });
}

/**
 * 负责按原顺序组合四个机制的公开普通狼刀目标查询。
 * 输入为当前目标序号、狼刀圈／角色政策及存活名单；输出为原候选允许布尔值。
 * 依次读取雾鸦狼刀圈、夜之贵族政策、存活名单、恶夜骑士及梦魇，短路与查询失败原样保留。
 * 绑定只捕获原 World 引用，不提前读组件、生命、库存或随机源；查询不公开 World 与提交写权。
 * 表面冻结不冻结 World 或复制名单，现场候选允许结果也不是实际狼刀提交许可。
 */
import type { EntityId } from "../../../../core/domain/identity";
import type { World } from "../../../../core/domain/world";
import { bindMistKnifeTargetQuery, type MistKnifeTargetQuery } from "../mist_raven/ports";
import { bindNobleKnifeTargetQuery, type NobleKnifeTargetQuery } from "../noble_secret_body/ports";
import {
  bindEvilKnightKnifeTargetQuery,
  type EvilKnightKnifeTargetQuery,
} from "../evil_knight/ports";
import {
  bindNightmareKnifeTargetQuery,
  type NightmareKnifeTargetQuery,
} from "../nightmare_shadow/ports";

/** 名单在 allows 内的原第三步才读取；返回原只读视图，不保存第二份阵容快照。 */
export interface WolfKnifeRosterQuery {
  aliveIds(): readonly EntityId[];
}
/** 仅提供目标谓词，不携带回合、能力实例或付款权限。 */
export interface WolfKnifeTargetQuery {
  allows(targetId: EntityId): boolean;
}

/** 固定组合顺序；保留每个查询的原 receiver 与短路，不新增可扩展规则图或角色回调注册器。 */
export function createWolfKnifeTargetQuery(
  roster: WolfKnifeRosterQuery,
  mist: MistKnifeTargetQuery,
  noble: NobleKnifeTargetQuery,
  evilKnight: EvilKnightKnifeTargetQuery,
  nightmare: NightmareKnifeTargetQuery,
): WolfKnifeTargetQuery {
  return Object.freeze({
    allows(targetId: EntityId) {
      const circle = mist.targets();
      return (
        (circle === null || circle.includes(targetId)) &&
        noble.allows(targetId) &&
        roster.aliveIds().includes(targetId) &&
        evilKnight.allows(targetId) &&
        nightmare.allows(targetId)
      );
    },
  });
}

/** 只捕获 World 参数引用，四个具体绑定仍按原顺序创建；所有现场查询延迟至 allows。 */
export function bindWolfKnifeTargetQuery(world: World): WolfKnifeTargetQuery {
  return createWolfKnifeTargetQuery(
    { aliveIds: () => world.getAliveEntityIds() },
    bindMistKnifeTargetQuery(world),
    bindNobleKnifeTargetQuery(world),
    bindEvilKnightKnifeTargetQuery(world),
    bindNightmareKnifeTargetQuery(world),
  );
}

/**
 * 负责驱动夜贵族子系统的原 World fixture、有界夜选择、伤害和关闭。输入为脚本步骤、回调与资源请求，输出为原受控轨迹、句柄及边界响应。测试保留字面行动和失败预期；不运行完整对局或传输，也不引入付费模型。
 */
import { createAliveComponent, createCampComponent } from "../../../../../src/game/observation/component-presentation";
import { World } from "../../../../../src/core/domain/world";
import { COMPONENT } from "../../../../../src/core/domain/components/names";
import { Role, Camp } from "../../../../../src/core/domain/identity";
import { createRoleComponent } from "../../../../../src/game/observation/role-presentation";
import { type AliveComponent } from "../../../../../src/core/domain/components/alive";

import { createVictoryComponent } from "../../../../../src/core/domain/components/victory";
import { createIdentityComponent } from "../../../../../src/core/domain/entities/player";
import {
  createNobleState,
  createSecretBodyState,
} from "../../../../../src/game/mechanisms/roles/noble_secret_body/state";
import {
  installNobleBodyAuthority,
  beginNobleBodyNight,
  openSecretBodyChoice,
  openServantChoice,
  expireServantAtNightEnd,
  resolveSecretBodyDamage,
  closeNobleBodyNight,
} from "../../../../../src/game/mechanisms/roles/noble_secret_body/authority";
/** Explicit subsystem fixture. Surrogate existing cards prove original-object ownership;
 * this does not register the two planned roles or pretend to run their game rules. */
export function nobleBodyAuthorityFixture() {
  const world = new World(),
    roles = [];
  for (let id = 1; id <= 6; id++) {
    const actual = world.createEntity(),
      camp = id === 1 ? Camp.Wolf : Camp.Good,
      role = createRoleComponent(id === 1 ? Role.Wolf : Role.Villager, camp);
    if (id === 1) (role.privateState as Record<string, unknown>).noble = createNobleState();
    if (id === 2)
      (role.privateState as Record<string, unknown>).secretBody = createSecretBodyState();
    world.addComponent(actual, COMPONENT.Role, role);
    world.addComponent(
      actual,
      COMPONENT.Identity,
      createIdentityComponent(actual, actual, `Synthetic ${actual}`),
    );
    world.addComponent(actual, COMPONENT.Camp, createCampComponent(camp));
    world.addComponent(
      actual,
      COMPONENT.Victory,
      createVictoryComponent([{ kind: "faction", faction: camp }]),
    );
    world.addComponent(actual, COMPONENT.Alive, createAliveComponent());
    roles.push(role);
  }
  installNobleBodyAuthority(world, 1, 2);
  const life = (id: number) => world.getComponent(id, COMPONENT.Alive)!;
  const finish = (day: number) => {
    expireServantAtNightEnd(world, day);
    closeNobleBodyNight(world, day, "normal");
    return resolveSecretBodyDamage(world, day, {});
  };
  const night = (
    day: number,
    bodyTarget: number | null = null,
    nobleTarget: number | null = null,
  ) => {
    beginNobleBodyNight(world, day, () => true);
    openSecretBodyChoice(world, day).commit(bodyTarget);
    if (day >= 2) openServantChoice(world, day).commit(nobleTarget);
  };
  return { world, roles, life, finish, night };
}
